#include "ui/Input.hpp"
#include "rendering/Renderer.hpp"
#include <algorithm>
namespace fg {
void Input::update(InputState&s,const World&,EventBus& events,SDL_Renderer* renderer,int width,int height,float dt){SDL_Event ev;while(SDL_PollEvent(&ev)){if(ev.type==SDL_QUIT)events.publish({EventType::QuitRequested});if(ev.type==SDL_KEYDOWN&&!ev.key.repeat){switch(ev.key.keysym.sym){case SDLK_ESCAPE:events.publish({EventType::QuitRequested});break;case SDLK_1:s.tool=Tool::Path;break;case SDLK_2:s.tool=Tool::FoodStall;break;case SDLK_3:s.tool=Tool::Toilet;break;case SDLK_4:s.tool=Tool::Stage;break;case SDLK_5:s.tool=Tool::Entrance;break;case SDLK_SPACE:events.publish({EventType::PauseToggled});break;case SDLK_n:events.publish({EventType::NextDayRequested});break;case SDLK_EQUALS:case SDLK_PLUS:case SDLK_KP_PLUS:s.zoom=std::min(2.5f,s.zoom+0.1f);break;case SDLK_MINUS:case SDLK_KP_MINUS:s.zoom=std::max(0.5f,s.zoom-0.1f);break;case SDLK_HOME:s.cameraX=0;s.cameraY=static_cast<int>((kMapWidth*kTileH/2.0f+34.0f-height/2.0f)/s.zoom);break;default:break;}}if(ev.type==SDL_MOUSEWHEEL){s.zoom=std::clamp(s.zoom+static_cast<float>(ev.wheel.y)*0.1f,0.5f,2.5f);}
 if(ev.type==SDL_MOUSEBUTTONDOWN){int x,y;SDL_GetMouseState(&x,&y);float lx{},ly{};SDL_RenderWindowToLogical(renderer,x,y,&lx,&ly);Renderer projection(nullptr,width,height,s.zoom);s.hover=projection.screenToTile(static_cast<int>(lx),static_cast<int>(ly),s.cameraX,s.cameraY);}}
 const Uint8*k=SDL_GetKeyboardState(nullptr);int speed=static_cast<int>(400*dt);if(k[SDL_SCANCODE_LEFT]||k[SDL_SCANCODE_A])s.cameraX-=speed;if(k[SDL_SCANCODE_RIGHT]||k[SDL_SCANCODE_D])s.cameraX+=speed;if(k[SDL_SCANCODE_UP]||k[SDL_SCANCODE_W])s.cameraY-=speed;if(k[SDL_SCANCODE_DOWN]||k[SDL_SCANCODE_S])s.cameraY+=speed;
 int mx,my;SDL_GetMouseState(&mx,&my);float lx{},ly{};SDL_RenderWindowToLogical(renderer,mx,my,&lx,&ly);Renderer projection(nullptr,width,height,s.zoom);s.hover=projection.screenToTile(static_cast<int>(lx),static_cast<int>(ly),s.cameraX,s.cameraY);
}
}
